PRAGMA foreign_keys = ON;
CREATE TABLE cases(case_id INTEGER PRIMARY KEY,case_number TEXT UNIQUE NOT NULL,case_type TEXT,title TEXT,jurisdiction TEXT,description TEXT,status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Closed','On Hold')),opened_at TEXT NOT NULL);
CREATE TABLE roles(role_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE departments(department_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE officers(officer_id INTEGER PRIMARY KEY,name TEXT NOT NULL,badge_number TEXT UNIQUE NOT NULL,role TEXT NOT NULL,department TEXT,email TEXT,status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')));
CREATE TABLE officer_auth(officer_id INTEGER PRIMARY KEY REFERENCES officers ON DELETE CASCADE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE evidence_types(evidence_type_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE evidence(evidence_id INTEGER PRIMARY KEY,case_id INTEGER NOT NULL REFERENCES cases,evidence_type TEXT NOT NULL,description TEXT NOT NULL,source TEXT,original_hash TEXT NOT NULL,hash_algorithm TEXT NOT NULL DEFAULT 'SHA-256' CHECK(hash_algorithm='SHA-256'),encrypted_object_ref TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Seized' CHECK(status IN ('Seized','Transferred','Under Review','Submitted','Archived')),created_at TEXT NOT NULL,current_custodian_id INTEGER REFERENCES officers,filename TEXT);
CREATE TABLE event_types(event_type_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE custody_events(event_id INTEGER PRIMARY KEY,evidence_id INTEGER NOT NULL REFERENCES evidence,from_officer_id INTEGER REFERENCES officers,to_officer_id INTEGER NOT NULL REFERENCES officers,event_type TEXT NOT NULL CHECK(event_type IN ('Seizure','Transfer')),event_time TEXT NOT NULL,location TEXT,purpose TEXT,event_hash TEXT NOT NULL,blockchain_status TEXT NOT NULL DEFAULT 'PENDING' CHECK(blockchain_status IN ('PENDING','ANCHORED','FAILED')),digital_signature TEXT);
CREATE TABLE access_logs(access_id INTEGER PRIMARY KEY,evidence_id INTEGER REFERENCES evidence,officer_id INTEGER REFERENCES officers,access_type TEXT NOT NULL,access_time TEXT NOT NULL,device_id TEXT,result TEXT NOT NULL CHECK(result IN ('Success','Failed')),reason TEXT);
CREATE TABLE courts(court_id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE court_submissions(submission_id INTEGER PRIMARY KEY,evidence_id INTEGER NOT NULL REFERENCES evidence,court_name TEXT NOT NULL,submitted_by INTEGER NOT NULL REFERENCES officers,submission_time TEXT NOT NULL,verification_result TEXT NOT NULL CHECK(verification_result IN ('Verified','Failed')));
CREATE TABLE permissions(permission_id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,description TEXT NOT NULL);
CREATE TABLE role_permissions(role_id INTEGER NOT NULL REFERENCES roles,permission_id INTEGER NOT NULL REFERENCES permissions,PRIMARY KEY(role_id,permission_id));
CREATE TABLE blockchain_anchors(anchor_id INTEGER PRIMARY KEY,record_type TEXT NOT NULL,record_id TEXT NOT NULL,record_hash TEXT NOT NULL,transaction_id TEXT UNIQUE NOT NULL,anchored_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','ANCHORED','FAILED')));
CREATE TABLE transaction_log(transaction_id INTEGER PRIMARY KEY,operation TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('SUCCESS','FAILURE')),details TEXT,recorded_at TEXT NOT NULL);
CREATE TABLE backup_history(backup_id INTEGER PRIMARY KEY,path TEXT NOT NULL,created_at TEXT NOT NULL,integrity_result TEXT NOT NULL);
CREATE INDEX idx_evidence_case ON evidence(case_id); CREATE INDEX idx_evidence_hash ON evidence(original_hash);
CREATE INDEX idx_events_evidence ON custody_events(evidence_id,event_time); CREATE INDEX idx_events_officer ON custody_events(to_officer_id,event_time);
CREATE INDEX idx_access_evidence ON access_logs(evidence_id,access_time); CREATE INDEX idx_access_officer ON access_logs(officer_id,access_time);
CREATE TRIGGER evidence_hash_immutable BEFORE UPDATE OF original_hash ON evidence WHEN OLD.original_hash IS NOT NEW.original_hash BEGIN SELECT RAISE(ABORT,'original evidence hash is immutable'); END;
CREATE TRIGGER custody_events_immutable_update BEFORE UPDATE ON custody_events WHEN OLD.evidence_id IS NOT NEW.evidence_id OR OLD.from_officer_id IS NOT NEW.from_officer_id OR OLD.to_officer_id IS NOT NEW.to_officer_id OR OLD.event_type IS NOT NEW.event_type OR OLD.event_time IS NOT NEW.event_time OR OLD.location IS NOT NEW.location OR OLD.purpose IS NOT NEW.purpose OR OLD.event_hash IS NOT NEW.event_hash BEGIN SELECT RAISE(ABORT,'custody events are append-only'); END;
CREATE TRIGGER custody_events_immutable_delete BEFORE DELETE ON custody_events BEGIN SELECT RAISE(ABORT,'custody events are append-only'); END;

CREATE TRIGGER evidence_status_valid_insert BEFORE INSERT ON evidence WHEN NEW.status NOT IN ('Seized','Transferred','Under Review','Submitted','Archived') BEGIN SELECT RAISE(ABORT,'invalid evidence status'); END;
CREATE TRIGGER evidence_status_valid_update BEFORE UPDATE OF status ON evidence WHEN NEW.status NOT IN ('Seized','Transferred','Under Review','Submitted','Archived') BEGIN SELECT RAISE(ABORT,'invalid evidence status'); END;
CREATE TRIGGER officer_role_valid_insert BEFORE INSERT ON officers WHEN NEW.role NOT IN ('Seizing Officer','Investigating Officer','Forensic Analyst','Storage Custodian','Court Officer','Auditor','Administrator') BEGIN SELECT RAISE(ABORT,'invalid officer role'); END;
CREATE TRIGGER custody_event_valid_insert BEFORE INSERT ON custody_events WHEN NEW.event_type NOT IN ('Seizure','Transfer') OR (NEW.event_type='Seizure' AND (NEW.from_officer_id IS NOT NULL OR NEW.to_officer_id != (SELECT current_custodian_id FROM evidence WHERE evidence_id=NEW.evidence_id))) OR (NEW.event_type='Transfer' AND (NEW.from_officer_id IS NULL OR NEW.from_officer_id != (SELECT current_custodian_id FROM evidence WHERE evidence_id=NEW.evidence_id))) BEGIN SELECT RAISE(ABORT,'invalid custody event'); END;
CREATE TRIGGER case_status_valid_insert BEFORE INSERT ON cases WHEN NEW.status NOT IN ('Open','Closed','On Hold') BEGIN SELECT RAISE(ABORT,'invalid case status'); END;
CREATE TRIGGER case_status_valid_update BEFORE UPDATE OF status ON cases WHEN NEW.status NOT IN ('Open','Closed','On Hold') BEGIN SELECT RAISE(ABORT,'invalid case status'); END;
CREATE TRIGGER officer_status_valid_insert BEFORE INSERT ON officers WHEN NEW.status NOT IN ('Active','Inactive') BEGIN SELECT RAISE(ABORT,'invalid officer status'); END;
CREATE TRIGGER access_result_valid_insert BEFORE INSERT ON access_logs WHEN NEW.result NOT IN ('Success','Failed') BEGIN SELECT RAISE(ABORT,'invalid access result'); END;
CREATE TRIGGER submission_result_valid_insert BEFORE INSERT ON court_submissions WHEN NEW.verification_result NOT IN ('Verified','Failed') BEGIN SELECT RAISE(ABORT,'invalid submission result'); END;
